import{_ as o,C as s,o as n,c as r,j as t,a as d,E as i,a2 as c}from"./chunks/framework.sc8Z_ZE3.js";const b=JSON.parse('{"title":"Checks and plan scope","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/plan-scope.md","filePath":"concepts/plan-scope.md"}'),p={name:"concepts/plan-scope.md"};function h(l,e,u,g,f,m){const a=s("Badge");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"checks-and-plan-scope",tabindex:"-1"},[d("Checks and plan scope "),t("a",{class:"header-anchor",href:"#checks-and-plan-scope","aria-label":'Permalink to "Checks and plan scope"'},"​")],-1)),i(a,{type:"built",text:"Built"}),e[1]||(e[1]=c(' Two rules keep a run honest about what it did and what it may touch: failed checks go back to the agent only a bounded number of times, and changes to expensive places need an approved plan. Both decide the same for Claude Code and Codex.<h2 id="bounded-retries" tabindex="-1">Bounded retries <a class="header-anchor" href="#bounded-retries" aria-label="Permalink to &quot;Bounded retries&quot;">​</a></h2><p>A failed check (a gate, the pipeline or CI) sends the work back to the agent <strong>at most N times</strong>. Then the run pauses as <code>checks_failed</code> and shows the failed checks, so red work is never reported as done.</p><ul><li><strong>N</strong> is a Workspace setting, <code>device_runs.check_attempts</code> (in <strong>Workspace settings › Coding tools &amp; devices</strong>): default <strong>3</strong>, from 1 to 20.</li><li>At the pause a person chooses: <strong>Retry</strong> with more iterations, <strong>Out of scope: follow-up issue</strong> (when the run has a ticket), or <strong>Re-clarify</strong>.</li></ul><h2 id="the-change-plan" tabindex="-1">The change plan <a class="header-anchor" href="#the-change-plan" aria-label="Permalink to &quot;The change plan&quot;">​</a></h2><p>A plan phase records its <strong>change plan</strong> as data, not as free text: the parts of the change, the paths, the endpoints, the expensive classes it touches, the risks and the open questions. A person approves it.</p><h3 id="expensive-paths" tabindex="-1">Expensive paths <a class="header-anchor" href="#expensive-paths" aria-label="Permalink to &quot;Expensive paths&quot;">​</a></h3><p>Some places are expensive to change. By default:</p><table tabindex="0"><thead><tr><th>Class</th><th>Paths</th></tr></thead><tbody><tr><td><code>migrations</code></td><td><code>**/migrations/**</code>, <code>**/alembic/**</code>, <code>**/*.sql</code></td></tr><tr><td><code>auth</code></td><td><code>**/auth/**</code>, <code>**/permissions/**</code>, <code>**/*rbac*</code></td></tr><tr><td><code>public_api</code></td><td><code>**/openapi*.json</code>, <code>**/openapi*.yaml</code>, <code>**/openapi*.yml</code>, <code>**/*.proto</code>, <code>**/schema.graphql</code> (the contract files only; routes and handlers are everyday work)</td></tr><tr><td><code>infra</code></td><td><code>Dockerfile*</code>, <code>**/deploy/**</code>, <code>**/k8s/**</code>, <code>**/helm/**</code>, <code>**/terraform/**</code>, <code>.github/workflows/**</code></td></tr></tbody></table><p>A Workspace sets its own classes with <code>device_runs.expensive_paths</code>; removing the setting brings back these defaults.</p><h3 id="what-the-agent-may-write" tabindex="-1">What the agent may write <a class="header-anchor" href="#what-the-agent-may-write" aria-label="Permalink to &quot;What the agent may write&quot;">​</a></h3><ul><li>A write to an expensive path needs an <strong>approved change plan</strong>. A plan that names no expensive class counts as approved.</li><li>With an approved plan, a write <strong>outside the plan&#39;s paths</strong> is refused until a person approves it.</li></ul><p>The run pauses as <code>needs_approval</code>. The pause offers <strong>Approve the change plan</strong> (for the plan) or <strong>Approve <code>&lt;path&gt;</code></strong> (for one path), and <strong>Change the plan</strong>.</p><h2 id="lint-in-the-pipeline" tabindex="-1">Lint in the pipeline <a class="header-anchor" href="#lint-in-the-pipeline" aria-label="Permalink to &quot;Lint in the pipeline&quot;">​</a></h2><p>The pipeline runs the repository&#39;s declared lint after its tests; a red lint is a red pipeline. The separate <code>lint_passed</code> check type is gone.</p><h2 id="also" tabindex="-1">Also <a class="header-anchor" href="#also" aria-label="Permalink to &quot;Also&quot;">​</a></h2><ul><li>A confirmation box continues with open high findings only when its definition says so (<code>on_open_high</code>).</li><li>A read-only workflow phase refuses a tool that no rule names.</li></ul><p>See <a href="/docs/concepts/workflows">Workflows</a> and <a href="/docs/concepts/evidence">Evidence and checks</a>.</p>',18))])}const _=o(p,[["render",h]]);export{b as __pageData,_ as default};
